create table audit_logs (created_at timestamp(6) with time zone not null, entity_id bigint not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, details varchar(500), action varchar(255) not null check ((action in ('CREATED','UPDATED','ARCHIVED','RESTORED','ACTIVATED','DEACTIVATED','HIDDEN','SHOWN','STOCK_ADJUSTED','STOCK_SET','IMAGE_UPLOADED','IMAGE_DELETED','COVER_CHANGED','ROLE_CHANGED','STATUS_CHANGED','SHIPMENT_STATUS_CHANGED','APPROVED','REJECTED','RECEIVED','REFUNDED'))), actor_email varchar(255) not null, entity_label varchar(255) not null, entity_type varchar(255) not null check ((entity_type in ('PRODUCT','VARIANT','ORDER','RETURN','DISCOUNT_CODE','REVIEW','TEAM_MEMBER'))), primary key (id));
create table cart_items (quantity integer not null, cart_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, product_sku_id bigint not null, updated_at timestamp(6) with time zone not null, primary key (id), constraint uk_cart_product_sku unique (cart_id, product_sku_id));
create table carts (created_at timestamp(6) with time zone not null, discount_code_id bigint, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_id bigint not null unique, primary key (id));
create table discount_codes (active boolean not null, discount_percentage integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, code varchar(255) not null unique, primary key (id));
create table order_items (discount_percentage integer not null, height_cm integer not null, length_cm integer not null, price numeric(12,2) not null, quantity integer not null, weight_grams integer not null, width_cm integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, order_id bigint not null, product_sku_id bigint not null, updated_at timestamp(6) with time zone not null, color varchar(255) not null check ((color in ('BLACK','BLUE','CYAN','GOLD','GRAY','GREEN','LIME','MAGENTA','MAROON','OLIVE','ORANGE','PINK','PURPLE','RED','SALMON','TEAL','WHITE','YELLOW'))), image_path varchar(255), product_name varchar(255) not null, size varchar(255) not null check ((size in ('ONE_SIZE','XS','S','M','L','XL','XXL','_15','_16','_17','_18','_19','_20','_21','_22','_23','_24','_25','_26','_27','_28','_29','_30','_31','_32','_33','_34','_35','_36','_37','_38','_39','_40','_41','_42','_43','_44','_45','_46'))), primary key (id), constraint uk_order_product_sku unique (order_id, product_sku_id));
create table order_return_items (quantity integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, order_item_id bigint not null, order_return_id bigint not null, updated_at timestamp(6) with time zone not null, primary key (id), constraint uk_return_order_item unique (order_return_id, order_item_id));
create table order_returns (manually_managed boolean not null, refund_amount numeric(12,2), approved_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, order_id bigint not null, received_at timestamp(6) with time zone, refunded_at timestamp(6) with time zone, rejected_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, comment varchar(500), reason varchar(500) not null check ((reason in ('DOES_NOT_FIT','DEFECTIVE','NOT_AS_DESCRIBED','CHANGED_MIND','OTHER'))), rejection_reason varchar(500), status varchar(255) not null check ((status in ('REQUESTED','APPROVED','REJECTED','RECEIVED','REFUNDED'))), stripe_refund_id varchar(255) unique, primary key (id));
create table order_shipment_items (quantity integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, order_item_id bigint not null, shipment_id bigint not null, updated_at timestamp(6) with time zone not null, primary key (id), constraint uk_shipment_order_item unique (shipment_id, order_item_id));
create table order_shipments (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, order_id bigint not null, updated_at timestamp(6) with time zone not null, shippo_transaction_id varchar(255) not null unique, status varchar(255) not null check ((status in ('PRE_TRANSIT','IN_TRANSIT','OUT_FOR_DELIVERY','FAILURE','DELIVERED'))), tracking_number varchar(255), primary key (id));
create table order_status_events (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, occurred_at timestamp(6) with time zone not null, order_id bigint not null, updated_at timestamp(6) with time zone not null, status varchar(255) not null check ((status in ('PENDING','CANCELED','FAILED','PAID','PROCESSING','SHIPPED','DELIVERED','RETURN_REQUESTED','REFUNDED','CANCELED_REFUNDED'))), primary key (id));
create table orders (currency varchar(3) not null, discount_percentage integer not null, manually_managed boolean not null, shipping_cost numeric(12,2) not null, tax_amount numeric(12,2) not null, total_amount numeric(12,2), created_at timestamp(6) with time zone not null, discount_code_id bigint, id bigint generated by default as identity, paid_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, user_id bigint not null, address_line1 varchar(255) not null, address_line2 varchar(255), city varchar(255) not null, country varchar(255) not null, phone varchar(255) not null, postal_code varchar(255) not null, recipient_name varchar(255) not null, shipping_carrier varchar(255) not null, shipping_service varchar(255) not null, state varchar(255), status varchar(255) not null check ((status in ('PENDING','CANCELED','FAILED','PAID','PROCESSING','SHIPPED','DELIVERED','RETURN_REQUESTED','REFUNDED','CANCELED_REFUNDED'))), stripe_checkout_session_id varchar(255) unique, stripe_payment_intent_id varchar(255) unique, primary key (id));
create table product_skus (active boolean not null, discount_percentage integer not null, height_cm integer not null, length_cm integer not null, stock integer not null, weight_grams integer not null, width_cm integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, product_id bigint not null, updated_at timestamp(6) with time zone not null, color varchar(255) not null check ((color in ('BLACK','BLUE','CYAN','GOLD','GRAY','GREEN','LIME','MAGENTA','MAROON','OLIVE','ORANGE','PINK','PURPLE','RED','SALMON','TEAL','WHITE','YELLOW'))), size varchar(255) not null check ((size in ('ONE_SIZE','XS','S','M','L','XL','XXL','_15','_16','_17','_18','_19','_20','_21','_22','_23','_24','_25','_26','_27','_28','_29','_30','_31','_32','_33','_34','_35','_36','_37','_38','_39','_40','_41','_42','_43','_44','_45','_46'))), primary key (id), constraint uk_product_size_color unique (product_id, size, color));
create table products (active boolean not null, discount_percentage integer not null, price numeric(12,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, description TEXT not null, category varchar(255) not null check ((category in ('OUTERWEAR','TOPS','BOTTOMS','FOOTWEAR','UNDERWEAR','ACCESSORIES'))), featured_slot varchar(255) check ((featured_slot in ('LEFT','RIGHT'))), name varchar(255) not null, ref varchar(255) not null unique, primary key (id), constraint uk_product_featured_slot unique (featured_slot));
create table product_sku_image (product_cover boolean not null, sku_cover boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, product_sku_id bigint not null, updated_at timestamp(6) with time zone not null, path varchar(255) not null, primary key (id));
create table refresh_tokens (revoked boolean not null, created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_id bigint not null, token varchar(255) not null unique, primary key (id));
create table reviews (hidden boolean not null, rating integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, product_id bigint not null, updated_at timestamp(6) with time zone not null, user_id bigint not null, description TEXT not null, title varchar(255) not null, primary key (id), constraint uk_user_product unique (user_id, product_id));
create table shipment_tracking_events (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, occurred_at timestamp(6) with time zone not null, shipment_id bigint not null, updated_at timestamp(6) with time zone not null, description varchar(500), location varchar(255), status varchar(255) not null check ((status in ('PRE_TRANSIT','IN_TRANSIT','OUT_FOR_DELIVERY','FAILURE','DELIVERED'))), primary key (id));
create table users (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, email varchar(255) not null unique, first_name varchar(255) not null, last_name varchar(255) not null, password varchar(255) not null, role varchar(255) not null check ((role in ('CUSTOMER','SUPPORT','FULFILLMENT','MERCHANDISER','MANAGER','ADMIN'))), stripe_customer_id varchar(255) unique, primary key (id));
create table wishlist_items (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, product_id bigint not null, updated_at timestamp(6) with time zone not null, wishlist_id bigint not null, primary key (id), constraint uk_wishlist_product unique (wishlist_id, product_id));
create table wishlists (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_id bigint not null unique, primary key (id));
alter table if exists cart_items add constraint fk_cart_item_cart foreign key (cart_id) references carts;
alter table if exists cart_items add constraint fk_cart_item_product_sku foreign key (product_sku_id) references product_skus;
alter table if exists carts add constraint fk_cart_discount_code foreign key (discount_code_id) references discount_codes;
alter table if exists carts add constraint fk_cart_user foreign key (user_id) references users;
alter table if exists order_items add constraint fk_order_item_order foreign key (order_id) references orders;
alter table if exists order_items add constraint fk_order_item_product_sku foreign key (product_sku_id) references product_skus;
alter table if exists order_return_items add constraint fk_return_item_order_item foreign key (order_item_id) references order_items;
alter table if exists order_return_items add constraint fk_return_item_return foreign key (order_return_id) references order_returns;
alter table if exists order_returns add constraint fk_order_return_order foreign key (order_id) references orders;
alter table if exists order_shipment_items add constraint fk_shipment_item_order_item foreign key (order_item_id) references order_items;
alter table if exists order_shipment_items add constraint fk_shipment_item_shipment foreign key (shipment_id) references order_shipments;
alter table if exists order_shipments add constraint fk_order_shipment_order foreign key (order_id) references orders;
alter table if exists order_status_events add constraint fk_order_status_event_order foreign key (order_id) references orders;
alter table if exists orders add constraint fk_order_discount_code foreign key (discount_code_id) references discount_codes;
alter table if exists orders add constraint fk_order_user foreign key (user_id) references users;
alter table if exists product_skus add constraint fk_product_sku_product foreign key (product_id) references products;
alter table if exists product_sku_image add constraint fk_product_sku_image_product_sku foreign key (product_sku_id) references product_skus;
alter table if exists refresh_tokens add constraint fk_refresh_token_user foreign key (user_id) references users;
alter table if exists reviews add constraint fk_review_product foreign key (product_id) references products;
alter table if exists reviews add constraint fk_review_user foreign key (user_id) references users;
alter table if exists shipment_tracking_events add constraint fk_tracking_event_shipment foreign key (shipment_id) references order_shipments;
alter table if exists wishlist_items add constraint fk_wishlist_item_product foreign key (product_id) references products;
alter table if exists wishlist_items add constraint fk_wishlist_item_wishlist foreign key (wishlist_id) references wishlists;
alter table if exists wishlists add constraint fk_wishlist_user foreign key (user_id) references users;
